<?php namespace App\Livewire\Vendor; use App\Actions\SaveFoodItemAction; use App\Models\Category; use App\Models\FoodItem; use Illuminate\Foundation\Auth\Access\AuthorizesRequests; use Livewire\Attributes\Layout; use Livewire\Component; #[Layout('layouts.app')] class ManageFoodItems extends Component { use AuthorizesRequests; public ?int $editingId = null; public string $category_id = ''; public string $name = ''; public string $description = ''; public string $price = ''; public bool $availability = true; public function save(SaveFoodItemAction $action): void { $stall = auth()->user()->stall; abort_if(!$stall, 403); $validated = $this->validate(['category_id' => ['required', 'exists:categories,id'], 'name' => ['required', 'string', 'max:255'], 'description' => ['nullable', 'string', 'max:1000'], 'price' => ['required', 'numeric', 'min:0.50'], 'availability' => ['boolean']]); if ($this->editingId) { $item = FoodItem::findOrFail($this->editingId); $this->authorize('update', $item); $action->execute($stall, $validated, $item); session()->flash('status', 'Food item updated.'); } else { $this->authorize('create', FoodItem::class); $action->execute($stall, $validated); session()->flash('status', 'Food item added.'); } $this->reset(['editingId', 'name', 'description', 'price']); $this->availability = true; } public function edit(int $id): void { $item = FoodItem::findOrFail($id); $this->authorize('update', $item); $this->editingId = $item->id; $this->category_id = (string) $item->category_id; $this->name = $item->name; $this->description = (string) $item->description; $this->price = (string) $item->price; $this->availability = (bool) $item->availability; } public function toggleAvailability(int $id, SaveFoodItemAction $action): void { $item = FoodItem::findOrFail($id); $this->authorize('update', $item); $action->execute($item->stall, ['category_id' => $item->category_id, 'name' => $item->name, 'description' => $item->description, 'price' => $item->price, 'availability' => !$item->availability], $item); } public function render() { $stall = auth()->user()->stall; $items = $stall ? FoodItem::with('category')->where('stall_id', $stall->id)->get() : collect(); return view('livewire.vendor.manage-food-items', ['items' => $items, 'categories' => Category::all()]); } }